CustomField.formula:
IF(
	BEGINS(Contact.MobilePhone,'0'),MID(Contact.MobilePhone, 2, LEN(Contact.MobilePhone)),
	IF(
		BEGINS(Contact.MobilePhone,Mobile_Country_Code_f__c),MID(Contact.MobilePhone, LEN(Mobile_Country_Code_f__c)+1, LEN(Contact.MobilePhone)),
		IF(
			BEGINS(Contact.MobilePhone,'61')||BEGINS(Contact.MobilePhone,'61') ,MID(Contact.MobilePhone, 3, LEN(Contact.MobilePhone)),
			Contact.MobilePhone
		)
	)	
)
